{
  "item": "DP-61",
  "epics": [
    {
      "id": "E1",
      "title": "Capture product identity on ingredients",
      "stories": [
        {
          "id": "S1",
          "statement": "As the pantry owner, I want an ingredient to optionally carry brand, barcode, and package size so a real branded product's identity is captured, not just its generic name.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "an ingredient is created with no brand, barcode, packageQuantity, or packageUnit supplied", "when": "the ingredient is saved", "then": "it saves successfully with those fields left unset"},
            {"id": "AC2", "given": "an ingredient is created with brand, barcode, packageQuantity, and packageUnit supplied", "when": "the ingredient is saved", "then": "all four values persist on the ingredient"},
            {"id": "AC3", "given": "an existing ingredient already has barcode \"012345\"", "when": "another ingredient is created or updated with barcode \"012345\"", "then": "the save is rejected for violating barcode uniqueness"},
            {"id": "AC4", "given": "two ingredients both have no barcode set", "when": "either is created or updated", "then": "neither save is rejected, since an absent barcode does not participate in the uniqueness check"}
          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Let out-of-stock products stay in the pantry",
      "stories": [
        {
          "id": "S2",
          "statement": "As the pantry owner, I want a pantry row to be allowed to hold zero quantity so running out of a product doesn't delete it from my pantry.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC5", "given": "a pantry row's quantity is updated down to 0", "when": "the update is saved", "then": "the row persists at quantity 0 instead of being rejected or removed"},
            {"id": "AC6", "given": "a pantry row already exists at quantity 0", "when": "the pantry is queried", "then": "that row is still returned, still linked to its ingredient"}
          ]
        },
        {
          "id": "S3",
          "statement": "As the pantry owner, I want a zero-quantity pantry item to visibly show as out of stock rather than look broken or disappear.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC7", "given": "a pantry row has quantity 0", "when": "I view the pantry page", "then": "the item is shown with an \"out of stock\" state rather than being hidden or erroring"},
            {"id": "AC8", "given": "a pantry row has quantity greater than 0", "when": "I view the pantry page", "then": "it renders normally with its quantity, not the out-of-stock state"}
          ]
        }
      ]
    },
    {
      "id": "E3",
      "title": "Create a branded custom item in one step from the pantry",
      "stories": [
        {
          "id": "S4",
          "statement": "As the pantry owner, I want a \"Create custom item\" button on /pantry that opens a single form, instead of hopping to /ingredients/new and back to /pantry.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC9", "given": "I am on /pantry", "when": "I click \"Create custom item\"", "then": "a form opens on the same page capturing the ingredient name, optional brand/barcode/package fields, and the initial pantry quantity"},
            {"id": "AC10", "given": "the create-custom-item form is open", "when": "I submit it with just a name and quantity", "then": "the brand, barcode, packageQuantity, and packageUnit fields are accepted as empty"}
          ]
        },
        {
          "id": "S5",
          "statement": "As the pantry owner, I want submitting the custom-item form to create the ingredient and its pantry row together, so there's no disconnected two-step flow and no partial result if it fails.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC11", "given": "a valid custom-item form submission", "when": "the Server Action runs", "then": "the new ingredient and its pantry row are both created by that single Server Action call"},
            {"id": "AC12", "given": "the submitted barcode already belongs to another ingredient", "when": "the Server Action runs", "then": "the action fails and neither the ingredient nor a pantry row is created"}
          ]
        }
      ]
    },
    {
      "id": "E4",
      "title": "Surface product identity in ingredient editing and pantry detail",
      "stories": [
        {
          "id": "S6",
          "statement": "As the pantry owner, I want the ingredient form to let me set brand, barcode, and package size, matching what the custom-item form captures.",
          "domains": ["ux", "backend"],
          "acceptance_criteria": [
            {"id": "AC13", "given": "I open the ingredient form to create or edit an ingredient", "when": "I fill in brand, barcode, packageQuantity, and packageUnit and save", "then": "those values are persisted on the ingredient"},
            {"id": "AC14", "given": "I open the ingredient form", "when": "I leave brand, barcode, packageQuantity, and packageUnit blank and save", "then": "the ingredient still saves successfully with those fields unset"}
          ]
        },
        {
          "id": "S7",
          "statement": "As the pantry owner, I want /pantry/[id] to show a product's brand, barcode, and package size when they're known.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC15", "given": "the pantry item's ingredient has brand, barcode, packageQuantity, and packageUnit set", "when": "I view /pantry/[id]", "then": "those fields are displayed on the page"},
            {"id": "AC16", "given": "the pantry item's ingredient has none of those fields set", "when": "I view /pantry/[id]", "then": "the page omits them rather than showing blank placeholders"}
          ]
        }
      ]
    }
  ]
}

