          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Support zero-quantity pantry rows as out-of-stock",
      "stories": [
        {
          "id": "S1",
          "statement": "As a user, I want a pantry row to remain valid at zero quantity so that running out of a product doesn't erase it from my pantry.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a pantry row's quantity is reduced to 0", "when": "the update is saved", "then": "the save succeeds instead of being rejected by a quantity > 0 constraint"},
            {"id": "AC2", "given": "a pantry row exists at quantity 0", "when": "the pantry is queried or listed", "then": "the row remains present rather than being deleted or hidden"}
          ]
        },
        {
          "id": "S2",
          "statement": "As a user, I want pantry rows at zero quantity to visibly read as out of stock so I can tell a depleted product from a stocked one.",
