            {"id": "AC12", "given": "no credentials are supplied", "when": "/metrics is scraped", "then": "it responds successfully without requiring authentication"}
          ]
        }
      ]
    },
    {
      "id": "E4",
      "title": "Configurable auth with fail-fast startup and backward-compatible dev mode",
      "stories": [
        {
          "id": "S6",
          "statement": "As an operator, I want authentication configuration validated at startup so that misconfiguration fails fast instead of degrading silently.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC13", "given": "an invalid auth configuration, such as a malformed key hash", "when": "the service starts", "then": "startup fails immediately with a clear configuration error"}
