      "stories": [
        {
          "id": "S1",
          "statement": "As an operator, I want GET /metrics on the existing HTTP port so Prometheus can scrape Hephaestus the same way it scrapes Apollo and Hermes",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "metrics.enabled is true", "when": "a client issues GET /metrics on the existing HTTP port", "then": "the response renders the app CollectorRegistry in Prometheus text format, alongside the existing /health route"},
            {"id": "AC2", "given": "the service starts with default configuration", "when": "no metrics.enabled value is set", "then": "metrics.enabled defaults to true and the /metrics route is registered"}
          ]
        },
        {
          "id": "S2",
          "statement": "As an operator, I want metrics.enabled=false to remove the endpoint and the recording overhead entirely",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "metrics.enabled is false", "when": "a client issues GET /metrics", "then": "no route is registered and the request does not reach a metrics handler"},
            {"id": "AC2", "given": "metrics.enabled is false", "when": "the service constructs its metrics component", "then": "a no-op MetricsRecorder is used so no collectors are registered and no recording work is performed"}
          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Base JVM metrics via the shared Prometheus client",
      "stories": [
        {
          "id": "S1",
          "statement": "As an operator, I want standard JVM metrics on /metrics so I can see Hephaestus's health the same way I see Apollo's and Hermes's",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "metrics.enabled is true", "when": "the app CollectorRegistry is built using the Prometheus simpleclient the sibling services use", "then": "base JVM collectors (memory, GC, threads) are registered in that registry"},
            {"id": "AC2", "given": "metrics.enabled is true", "when": "GET /metrics is scraped", "then": "the base JVM metrics appear in the response output in the same format sibling services expose"}
          ]
        }
      ]
    },
    {
      "id": "E3",
      "title": "Worker metrics through a MetricsRecorder seam in JobConsumer",
      "stories": [
        {
          "id": "S1",
          "statement": "As an operator, I want JobConsumer to record per-lane, per-outcome job counts so I can see worker throughput and failure rate",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a MetricsRecorder is injected into JobConsumer", "when": "a job finishes processing", "then": "a jobs-processed counter is incremented, labeled by lane and outcome"},
            {"id": "AC2", "given": "metrics.enabled is false", "when": "a job finishes processing", "then": "the no-op MetricsRecorder receives the call and records nothing"}
          ]
        },
        {
          "id": "S2",
          "statement": "As an operator, I want processing-time and in-flight visibility so I can see job latency and backlog pressure",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a job completes processing", "when": "JobConsumer reports the outcome to MetricsRecorder", "then": "a processing-time histogram observation is recorded for that job"},
            {"id": "AC2", "given": "a job starts processing", "when": "JobConsumer begins work on it", "then": "an in-flight gauge is incremented, and decremented when the job finishes or fails"}
          ]
        }
      ]
    }
  ]
}

