            {"id": "AC2", "given": "an operator requests a message identifier that is not in the DLQ", "when": "the inspect endpoint is called", "then": "it returns a not-found response rather than a partial or malformed result"}
          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Redrive dead-lettered messages back onto the subscription",
      "stories": [
        {
          "id": "S3",
          "statement": "As an operator, I can redrive a specific set of selected dead-letter messages back onto their subscription for another delivery attempt.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "an operator selects a set of dead-lettered message identifiers on a subscription", "when": "they call the redrive endpoint with that selection", "then": "each selected message is re-enqueued onto the subscription for delivery and removed from the dead-letter queue"},
            {"id": "AC2", "given": "a redrive request includes an identifier not present in the DLQ", "when": "the redrive endpoint processes the request", "then": "the valid messages in the selection are redriven and the invalid identifier is reported without failing the entire request"}
          ]
        },
        {
          "id": "S4",
          "statement": "As an operator, I can redrive all dead-lettered messages for a subscription in one call instead of selecting them individually.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a subscription has multiple dead-lettered messages", "when": "an operator calls redrive-all for that subscription", "then": "every message currently in the subscription's DLQ is re-enqueued for delivery and the DLQ for that subscription is emptied"},
            {"id": "AC2", "given": "a redrive-all call is in progress", "when": "a new message is dead-lettered on the same subscription during that call", "then": "the newly dead-lettered message is not redriven by the in-progress call"}
