          "acceptance_criteria": [
            {"id": "AC1", "given": "a dead-letter message has already been successfully redriven", "when": "the same redrive request is submitted again", "then": "no duplicate delivery attempt or duplicate enqueue occurs as a result of the repeated request"},
            {"id": "AC2", "given": "a subscription has messages currently in flight for delivery alongside messages in its dead-letter queue", "when": "an operator redrives the dead-lettered messages", "then": "the in-flight messages' delivery state and ordering are unaffected by the redrive"}
          ]
        }
      ]
    }
  ]
}

